param([string]$Workspace='D:/opencode/conversao-sc')
$ErrorActionPreference='Stop'
$inventoryPath=Join-Path $Workspace 'integration-src/ciw-inventory/inventory-reviewed.json'
$catalogPath=Join-Path $Workspace '.runtime/ciw-completion-20261028/catalog-before.json'
$inventory=Get-Content -LiteralPath $inventoryPath -Raw|ConvertFrom-Json
$catalog=Get-Content -LiteralPath $catalogPath -Raw|ConvertFrom-Json
function Evidence([string]$RelativePath,[string]$Role) {
 $path=Join-Path $Workspace $RelativePath
 [pscustomobject]@{path=$RelativePath;role=$Role;exists=(Test-Path -LiteralPath $path);sha256=$(if(Test-Path -LiteralPath $path){(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()}else{$null})}
}
function Proposal([string]$Application,[string]$Disposition,[string]$Screen,[string]$Remaining,[string[]]$Documents,[string[]]$Receipts,[string[]]$Limitations) {
 $entry=$inventory.entries|Where-Object {$_.name -eq $Application}
 [pscustomobject][ordered]@{application=$Application;baselineState=$entry.state_group;baselineRemaining=$entry.remaining;disposition=$Disposition;targetScreen=$Screen;catalog=@($catalog.programs|Where-Object {$_.screenId -eq $Screen}|Select-Object code,screenId,publishedVersion,status);proposedRemaining=$Remaining;limitations=$Limitations;evidence=@(@($Documents|ForEach-Object {Evidence $_ 'source-or-public-document'})+@($Receipts|ForEach-Object {Evidence $_ 'private-receipt-reference-no-content-copied'}));globalInventoryChanged=$false;rootReviewRequired=$true}
}
$proposals=@(
 (Proposal 'bl_sincronizar_impostos' 'eligible-recorded-complete-after-root-check' 'ciw.container-sincronizar-impostos' 'ProcessEngine op1017 ja publicado: contexto container fixo, servico fiscal central, confirmacao Kendo, auditoria e cenario novo concluido/limpo em16/10. Nao reexecutar.' @('sources/scriptcase/containers/bl_sincronizar_impostos/index.php','docs/painel-container-comandos.md') @('.runtime/container-commands-publish-20261016/active-manifest.json','.runtime/container-commands-20261016/http-exercise-evidence.json','.runtime/container-commands-20261016/command-cleanup-verification.json') @('Comparacao de origem por evento ativo: index5470-5471 chama sincronizarImpostos; formulas permanecem no servico central.','Catalogo28/10 comprova publicacao; recibos de negocio sao historicos validos, nao nova execucao28/10.'))
 (Proposal 'cons_tit_ap_associados_container' 'correct-stale-remaining-preserve-limit' 'ciw.container-pagamentos' 'Consulta22campos/read/get, inclusao via opcoes e desassociacao ja publicadas emop1006/1.0.2. Adiantamento/duplicidade/estorno/efeitos/Logs e limpeza comprovados em19/10. Nao manter pendencia generica de associacao/desassociacao. Conferir limite do ramo aposDI, selecao individual versus lote e acesso visual humano vigente.' @('sources/scriptcase/containers/cons_tit_ap_associados_container/cons_tit_ap_associados_container_grid.class.php','docs/painel-container-pagamentos.md','docs/containers-pagamentos-associacoes-inventario.md') @('.runtime/container-payments-publish-20261017/active-manifest.json','.runtime/container-payments-20261017/runtime-read-evidence.json','.runtime/container-payments-20261017/payments-final-cleanup-verification.json') @('Ramo de escrita aposDI nao foi exercitado no cenario19/10.','Legado tem selecao multipla; produto atual seleciona um titulo por operacao. Nao presumir equivalencia de lote.','UIvisual19/10 nao foi repetida; doc17/10 comprova UI original.'))
 (Proposal 'cons_tit_ap_associar_container' 'correct-stale-remaining-preserve-limit' 'ciw.container-pagamentos' 'Elegibilidade central de adiantamentos, opcoes contextuais e create fixo publicados; adiantamento+duplicidade+efeitos auditados comprovados e teste limpo. Reconciliar selecao multipla legada versus operacao individual nativa e navegacao contextual antes de equivalencia integral.' @('sources/scriptcase/containers/cons_tit_ap_associar_container/cons_tit_ap_associar_container_grid.class.php','docs/painel-container-pagamentos.md','docs/containers-pagamentos-associacoes-inventario.md') @('.runtime/container-payments-publish-20261017/active-manifest.json','.runtime/container-payments-20261017/payments-final-cleanup-verification.json') @('Nao marcar lote convertido por create individual.','Nao refazer adiantamento operacional para gerar prova.'))
 (Proposal 'cons_tit_ap_associar_container_apos_di' 'correct-stale-remaining-preserve-limit' 'ciw.container-pagamentos' 'Elegibilidade/opcoes centrais aposDI e mesmo create fixo ja publicados e testados emTT; opcoes reais17/10 continham modalidade aposDI. Escrita aposDI nao exercitada operacionalmente; dois titulos foram apenas lidos/preservados no cenario19/10. Reconciliar lote/navegacao sem inventar bloqueio DI/NF.' @('sources/scriptcase/containers/cons_tit_ap_associar_container_apos_di/cons_tit_ap_associar_container_apos_di_grid.class.php','docs/painel-container-pagamentos.md','docs/containers-pagamentos-associacoes-inventario.md') @('.runtime/container-payments-publish-20261017/active-manifest.json','.runtime/container-payments-20261017/runtime-read-evidence.json','.runtime/container-payments-20261017/payments-final-cleanup-verification.json') @('Sem teste operacional aposDI; manter gate especifico caso exigido.','Selecao multipla nao comprovada por create individual.'))
 (Proposal 'grid_itens_container' 'correct-stale-remaining-preserve-limit' 'ciw.container-itens' 'Leitura/custos centrais e manutencao/alocacao individual publicadas; selecao/alocacao emlote tambem concluida separadamente emop1025/1.0.0 em26/10 com teste limpo. Nao manter selecao emlote como pendente generica. Calcular custo unitario/fechamento e demais acoes proprias ainda devem ser comparados por origem.' @('sources/scriptcase/containers/grid_itens_container/grid_itens_container_grid.class.php','docs/painel-container-itens.md','docs/ciw-alocacao-lote-container-2026-10-26.md') @('.runtime/container-allocation-batch-20261026/final-verification.json') @('Nao declarar toda grade convertida pela existencia da tela semelhante.','Loteop1025 possui escopo/regras documentados; nao equivale automaticamente a todos chamadores globais.'))
)
$out=[ordered]@{generatedAt=(Get-Date).ToUniversalTime().ToString('o');inventoryBaselineSha256=(Get-FileHash -LiteralPath $inventoryPath -Algorithm SHA256).Hash.ToLowerInvariant();catalogBaselineSha256=(Get-FileHash -LiteralPath $catalogPath -Algorithm SHA256).Hash.ToLowerInvariant();proposalCount=$proposals.Count;globalInventoryChanged=$false;proposals=$proposals}
$out|ConvertTo-Json -Depth 14|Set-Content -LiteralPath (Join-Path $Workspace '.runtime/ciw-completion-20261028/reconciliation-proposal.json') -Encoding utf8
[pscustomobject]@{proposalCount=$proposals.Count;missingEvidence=@($proposals.evidence|Where-Object {-not $_.exists}).Count;catalogMatches=@($proposals.catalog).Count}|ConvertTo-Json
